%{
#include <stdio.h>
int yylex(void);
void yyerror(char *s);
%}
%token NUM
%start top
%left '+' '-'
%left '*' '/'
%%
top: top expr '\n' { printf("%d\n", $2); }
   | expr '\n' { printf("%d\n", $1); }
   ;
expr: expr '+' expr { $$ = $1 + $3; }
    | expr '-' expr { $$ = $1 - $3; }
    | expr '*' expr { $$ = $1 * $3; }
    | expr '/' expr { $$ = $1 / $3; }
    | '(' expr ')' { $$ = $2; }
    | NUM { $$ = $1; }
    ;
%%
int main(void) { return yyparse(); }
void yyerror(char *s) { fprintf(stderr, "%s\n", s); }
